import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"40、【解】 坎下震上","description":"周易口訣義 - 40、【解】 坎下震上","frontmatter":{"title":"40、【解】 坎下震上","description":"周易口訣義 - 40、【解】 坎下震上"},"headers":[],"relativePath":"classics/koujueyi/042.md","filePath":"classics/koujueyi/042.md"}'),r={name:"classics/koujueyi/042.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_40、【解】-坎下震上" tabindex="-1">40、【解】 坎下震上 <a class="header-anchor" href="#_40、【解】-坎下震上" aria-label="Permalink to “40、【解】 坎下震上”">​</a></h1><p>彖曰：「解」，險以動，動而免乎險，解。「解利西南」，往得眾也。「其來複吉」，乃得中也。「有攸往，夙吉」，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼，解之時大矣哉！</p><p>象曰：雷雨作，解，君子以赦過宥罪。</p><p>初六，無咎。</p><p>象曰：剛柔之際，義無咎也。</p><p>九二，田獲三狐，得黃矢，貞吉。</p><p>象曰：九二「貞吉」，得中道也。</p><p>六三，負且乘，致寇至，貞吝。</p><p>象曰：「負且乘」，亦可醜也。自我致戎，又誰咎也！</p><p>九四，解而拇，朋至斯孚。</p><p>象曰：「解而拇」，未當位也。</p><p>六五，君子維有解，吉。有孚於小人。</p><p>象曰：君子有解，小人退也。</p><p>上六，公用射隼於高墉之上，獲之無不利。</p><p>象曰：「公用射隼」，以解悖也。</p><p>解讀</p><p>解利西南者，解，緩也，謂難道解釋，物情舒緩，故謂「解」也。西南坤位，坤訓眾也，夫散難釋險，利施於眾，即所濟弘大，故曰「利西南」也。無所往其來複吉者，若難道已散，無難可救，即宜反覆守其靜默，即合於常理也。「有攸往夙吉」者，夙，早也，速也，若難道方殷，慮其侵傷平人，必須速往救濟，以安險俗，故曰「夙吉」。象曰「雷雨作，解」者，雷既發動，雨澤施降，物情舒暢，故是解緩之象也。「君子以赦過宥罪」者，赦，放也；宥，寬也；過謂誤犯，罪謂故為，過輕即放舍，罪重即寬宥，如似合死從流，合流從徒，皆是緩其罪刑也。</p><p>「初六無咎」者，難道已散，上有所應，故「無咎」也。</p><p>「九二，田獲三狐，得黃矢，貞吉」者，隱伏之物，喻犴猾之人。九二以剛居其位，為君委任，能散險難，能除奸暴之人，如似田獵而獲三狐，能持中直之道而令其正，故曰「得黃矢，貞吉」也。</p><p>「六三負且乘，致寇至，貞吝」者，六三位既不正，而以諂媚上附九四，下乘於二，如似擔負之人乘君子之乘，即寇盜必見其侵傷，故曰「負且乘，致寇至」。以不正之身，雖幸而免，是正人之所賤，故曰「貞吝」也。</p><p>「九四，解而拇，朋至斯孚」者，拇，足指也；而，汝也。九四位既不正，三亦不正，以相親比，三附於四，如指附足。然九四本應在初，若與三相附，即失其本應。若四能棄三之拇，即初六之朋與己合信，故曰「朋至斯孚」也。</p><p>六五：君子維有解，吉。「有孚於小人」者，以柔居尊，不自專制，而委九二，任用得人，是有君子之德，而能解釋險難，故曰「君子維有解，吉」也。以君子之道而能散難，即小人雖伏闇昧，亦能信服君子，不敢為非，故曰「有孚於小人」也。</p><p>上六：公用射隼於高墉之上，獲之，無不利者，公者，臣之極貴者也。上六以陽居極，故稱「公」也。居動之上，為解之極，是能去貪暴，除兇悖，故以「射隼」論之。隼者，貪賤之鳥，鷹鸇之屬，為六三失位不正。隼之為鳥，宜居山林，而止於人家墉牆之上，即為人所憎，射之克中，故曰「獲之，無不利」也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
